  data =  $input.first().json.data // "Accept" or "Revise"
}

return [{
  json: {
    chatId,
    text,
    message_id,
    data
  }
}];

// Pobierz output AI z poprzedniego węzła
let aiOutput = $('Telegram Trigger').first().json.callback_query.message.text;

// Obsługa błędów: sprawdź, czy output istnieje
if (!aiOutput || aiOutput.trim() === '') {
  throw new Error('Output AI jest pusty. Nie można wygenerować audio.');
}

// Podziel tekst na linie
let lines = aiOutput.split('\n');

// Usuń pierwszą linię, jeśli zawiera "Here is your generated prayer:"
if (lines[0].includes('Here is your generated prayer:')) {
  lines.shift();
}

// Usuń ostatnią linię, jeśli zawiera "This message was sent automatically with n8n"
if (lines[lines.length - 1].includes('This message was sent automatically with n8n')) {
  lines.pop();
}

// Połącz linie, zastępując nowe linie trzema kropkami
let cleanedOutput = lines.join('...').replace(/\s+/g, ' ').trim();

// Zwróć obiekt dla węzła HTTP Request
return [
  {
    json: {
      text: cleanedOutput, // oczyszczony tekst z "..."
      model_id: "eleven_flash_v2",
      voice_settings: {
        stability: 0.5,
        similarity_boost: 0.75
      }
    }
  }
];

