const transcription = $json; // English transcription from previous node

// Helper to format time
function formatTime(seconds) {
  const date = new Date(null);
  date.setSeconds(seconds);
  const ms = Math.floor((seconds % 1) * 1000);
  return date.toISOString().substr(11, 8) + ',' + ms.toString().padStart(3, '0');
}

const words = transcription.words.filter(w => w.type === 'word');
if (!words.length) throw new Error("No words in transcription");

let srt = '';
let counter = 1;
const maxWordsPerBlock = 5;

for (let i = 0; i < words.length; i += maxWordsPerBlock) {
  const blockWords = words.slice(i, i + maxWordsPerBlock);
  const start = formatTime(blockWords[0].start);
  const end = formatTime(blockWords[blockWords.length - 1].end);
  srt += `${counter}\n${start} --> ${end}\n${blockWords.map(w => w.text).join(' ')}\n\n`;
  counter++;
}

return [
  {
    binary: {
      data: {
        data: Buffer.from(srt),
        mimeType: 'application/x-subrip',
        fileName: 'English.srt'
      }
    }
  }
];

