// Fetch outputs from previous nodes
const audioData = $('Code3').all(); // Contains Polish, Chinese, English audio & content
const subtitleData = $('Code13').all(); // Contains Polish, Chinese, English subtitles

// Prepare a map to join audio data with subtitles using MessageId
const subtitlesMap = {};
for (const item of subtitleData) {
    const json = item.json;
    subtitlesMap[json.MessageId] = {  
        "English-subtitles": json["English-subtitles"]
    };
}

// Combine audio data and subtitles into a single array
const combinedRows = audioData.map(item => {
    const json = item.json;
    const messageId = json.MessageId;
    const subs = subtitlesMap[messageId] || {};

    return {
        json: {
            "MessageId": messageId,
            "English-Content": json["English-Content"],
            "English-audio-preview": json["English-audio-preview"],
            "English-audio-download": json["English-audio-download"],
            "English-Subtitles": subs["English-subtitles"],
        }
    };
});

return combinedRows;

